"use client";

// pages/dashboards/Staff/StaffAnnouncements.jsx
import { useMemo, useState } from "react";
import Link from "next/link";
import Layout from "@/components/Layout";
import { StaffMenuItems } from "@/utils/menus";
/* ---------- UI helpers ---------- */
const Card = ({ className = "", children }) => (
  <div className={`bg-white border border-gray-200/70 rounded-2xl shadow-none ${className}`}>{children}</div>
);

const Pill = ({ children, tone = "default" }) => {
  const styles =
    tone === "danger"
      ? "bg-red-50 text-red-700 ring-red-100"
      : tone === "success"
      ? "bg-emerald-50 text-emerald-700 ring-emerald-100"
      : tone === "warn"
      ? "bg-amber-50 text-amber-800 ring-amber-100"
      : tone === "purple"
      ? "bg-purple-50 text-purple-700 ring-purple-100"
      : tone === "muted"
      ? "bg-gray-50 text-gray-700 ring-gray-100"
      : "bg-blue-50 text-blue-700 ring-blue-100";

  return (
    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-semibold ring-1 ${styles}`}>
      {children}
    </span>
  );
};

const inputBase =
  "w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 bg-white focus:outline-none focus:ring-2 focus:ring-blue-100";

const btnBase = "px-5 py-3 rounded-2xl font-semibold active:scale-[0.99] transition";
const btnOutline = `${btnBase} border bg-white hover:bg-gray-50`;
const btnSolid = `${btnBase} text-white`;

const announcementsData = [
  {
    id: 'ANN-001',
    title: 'Safety Protocol Update - December 2024',
    message: 'Please review the updated safety protocols that will take effect from January 1, 2025. All staff must complete the mandatory safety training by December 31, 2024.',
    createdBy: 'HSE Department',
    createdDate: '2024-12-10T09:30:00',
    scope: 'All Company',
    priority: 'IMPORTANT',
    expiresAt: '2024-12-31',
    read: true,
    documents: 2,
    comments: 12
  },
  {
    id: 'ANN-002',
    title: 'Year-End Holiday Schedule',
    message: 'Company will be closed from December 24, 2024 to January 2, 2025 for the year-end holidays. Emergency contact numbers have been posted on the notice board.',
    createdBy: 'HR Department',
    createdDate: '2024-12-08T14:15:00',
    scope: 'All Company',
    priority: 'NORMAL',
    expiresAt: '2024-12-24',
    read: true,
    documents: 1,
    comments: 8
  },
  {
    id: 'ANN-003',
    title: 'Team Building Event - Save the Date',
    message: 'Annual team building event scheduled for December 18, 2024 at the company grounds. All staff are required to attend. Lunch will be provided.',
    createdBy: 'Admin Department',
    createdDate: '2024-12-05T11:00:00',
    scope: 'All Company',
    priority: 'NORMAL',
    expiresAt: '2024-12-18',
    read: false,
    documents: 0,
    comments: 5
  },
  {
    id: 'ANN-004',
    title: 'New Tender Announcement',
    message: 'New tender for IT equipment upgrade has been posted. All departments should review the requirements and provide feedback to procurement by December 12.',
    createdBy: 'Procurement Department',
    createdDate: '2024-12-04T10:45:00',
    scope: 'All Company',
    priority: 'IMPORTANT',
    expiresAt: '2024-12-12',
    read: true,
    documents: 3,
    comments: 15
  },
  {
    id: 'ANN-005',
    title: 'Technical Department Meeting',
    message: 'Important technical department meeting scheduled for December 11, 2024 at 2 PM. All technical staff must attend with their project updates.',
    createdBy: 'Technical HOD',
    createdDate: '2024-12-03T16:20:00',
    scope: 'Technical Department',
    priority: 'URGENT',
    expiresAt: '2024-12-11',
    read: false,
    documents: 1,
    comments: 3
  },
  {
    id: 'ANN-006',
    title: 'Workshop Safety Inspection',
    message: 'Quarterly workshop safety inspection will be conducted on December 12, 2024. All workshop staff should ensure their areas are properly organized and safety compliant.',
    createdBy: 'Workshop Manager',
    createdDate: '2024-12-02T13:30:00',
    scope: 'Workshop Department',
    priority: 'IMPORTANT',
    expiresAt: '2024-12-12',
    read: true,
    documents: 2,
    comments: 6
  },
];

const priorityTone = (priority) => {
  switch (priority) {
    case "URGENT": return "danger";
    case "IMPORTANT": return "warn";
    case "HIGH": return "warn";
    case "NORMAL": return "success";
    default: return "muted";
  }
};

const scopeTone = (scope) => {
  switch (scope) {
    case "All Company": return "purple";
    case "Technical Department": return "info";
    case "Workshop Department": return "warn";
    default: return "muted";
  }
};

const formatDate = (dateString) => {
  const date = new Date(dateString);
  return date.toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
};

const isExpired = (expiresAt) => new Date(expiresAt) < new Date();

export default function StaffAnnouncements() {
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");

  const unreadCount = useMemo(() => announcementsData.filter((a) => !a.read).length, []);
  const urgentCount = useMemo(() => announcementsData.filter((a) => a.priority === "URGENT").length, []);
  const importantCount = useMemo(() => announcementsData.filter((a) => a.priority === "IMPORTANT" && !a.read).length, []);

  const filteredAnnouncements = useMemo(() => {
    return announcementsData.filter((ann) => {
      if (filter === "unread" && ann.read) return false;
      if (filter === "important" && ann.priority !== "IMPORTANT" && ann.priority !== "URGENT") return false;
      if (filter === "technical" && ann.scope !== "Technical Department") return false;
      if (filter === "workshop" && ann.scope !== "Workshop Department") return false;
      if (filter === "company" && ann.scope !== "All Company") return false;

      if (search) {
        const q = search.toLowerCase();
        if (!ann.title.toLowerCase().includes(q) && !ann.message.toLowerCase().includes(q)) return false;
      }
      return true;
    });
  }, [filter, search]);

  const markAsRead = (id) => alert(`Marked announcement ${id} as read`);

  return (
    <Layout menuItems={StaffMenuItems} userRole="Staff">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* HERO */}
        <Card className="overflow-hidden">
          <div
            className="p-6 md:p-8"
            style={{
              background:
                "linear-gradient(135deg, rgba(44,75,155,0.10) 0%, rgba(109,198,223,0.18) 50%, rgba(237,50,55,0.06) 100%)",
            }}
          >
            <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
              <div>
                <div className="flex flex-wrap items-center gap-2 mb-2">
                  <Pill>📢 Announcements</Pill>
                  <Pill tone="success">Unread: {unreadCount}</Pill>
                  <Pill tone={importantCount ? "warn" : "muted"}>Important: {importantCount}</Pill>
                </div>

                <h1 className="text-2xl md:text-3xl font-extrabold tracking-tight" style={{ color: "var(--primary-blue)" }}>
                  Announcements
                </h1>
                <p className="text-gray-600 mt-2">Stay updated with company news and important announcements.</p>
              </div>

              <div className="flex flex-col sm:flex-row gap-2">
                <Link href="/staff-dashboard">
                  <button className={btnOutline} style={{ borderColor: "rgba(44,75,155,0.35)", color: "var(--primary-blue)" }}>
                    Back to Dashboard
                  </button>
                </Link>
              </div>
            </div>

            {/* FILTER BAR */}
            <div className="mt-6 grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-4">
              <div className="flex flex-wrap gap-2">
                {[
                  { id: "all", label: "All" },
                  { id: "unread", label: `Unread (${unreadCount})` },
                  { id: "important", label: "Important/Urgent" },
                  { id: "company", label: "Company" },
                  { id: "technical", label: "Technical" },
                  { id: "workshop", label: "Workshop" },
                ].map((f) => {
                  const active = filter === f.id;
                  const bg =
                    f.id === "unread"
                      ? active
                        ? "var(--secondary-blue)"
                        : "transparent"
                      : f.id === "important"
                      ? active
                        ? "rgba(245,158,11,1)"
                        : "transparent"
                      : f.id === "company"
                      ? active
                        ? "rgba(139,92,246,1)"
                        : "transparent"
                      : f.id === "technical"
                      ? active
                        ? "rgba(59,130,246,1)"
                        : "transparent"
                      : f.id === "workshop"
                      ? active
                        ? "rgba(245,158,11,1)"
                        : "transparent"
                      : active
                      ? "var(--primary-blue)"
                      : "transparent";

                  const border =
                    f.id === "unread"
                      ? "var(--secondary-blue)"
                      : f.id === "important"
                      ? "rgba(245,158,11,1)"
                      : f.id === "company"
                      ? "rgba(139,92,246,1)"
                      : f.id === "technical"
                      ? "rgba(59,130,246,1)"
                      : f.id === "workshop"
                      ? "rgba(245,158,11,1)"
                      : "var(--primary-blue)";

                  const color = active ? "white" : border;

                  return (
                    <button
                      key={f.id}
                      onClick={() => setFilter(f.id)}
                      className="px-4 py-2 rounded-2xl text-sm font-semibold border active:scale-[0.99] transition"
                      style={{
                        backgroundColor: bg,
                        borderColor: active ? "transparent" : border,
                        color,
                      }}
                    >
                      {f.label}
                    </button>
                  );
                })}
              </div>

              <div className="relative">
                <input
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search announcements..."
                  className={inputBase}
                />
                <span className="absolute left-3 top-3.5 text-gray-400">🔎</span>
              </div>
            </div>
          </div>
        </Card>

        {/* URGENT BANNER */}
        {urgentCount > 0 && filter !== "important" && (
          <Card className="p-5 border-red-200 bg-red-50">
            <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 rounded-2xl bg-white/70 flex items-center justify-center text-2xl">🚨</div>
                <div>
                  <p className="font-extrabold text-red-800">Urgent announcements need your attention</p>
                  <p className="text-sm text-red-700 mt-0.5">{urgentCount} urgent announcement(s) unread</p>
                </div>
              </div>
              <button
                className={btnSolid}
                style={{ backgroundColor: "rgba(239,68,68,1)" }}
                onClick={() => setFilter("important")}
              >
                View Urgent
              </button>
            </div>
          </Card>
        )}

        {/* LIST */}
        <div className="grid grid-cols-1 gap-4">
          {filteredAnnouncements.map((a) => {
            const expired = isExpired(a.expiresAt);
            return (
              <Card key={a.id} className={`overflow-hidden ${!a.read ? "ring-2 ring-blue-200" : ""} ${expired ? "opacity-80" : ""}`}>
                <div className="p-6">
                  <div className="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4">
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2 mb-3">
                        {!a.read && <span className="w-2.5 h-2.5 rounded-full bg-blue-500" />}
                        <Pill tone={priorityTone(a.priority)}>{a.priority}</Pill>
                        <Pill tone={scopeTone(a.scope)}>{a.scope}</Pill>
                        {expired ? <Pill tone="muted">Expired</Pill> : null}
                      </div>

                      <h3 className="text-lg font-extrabold text-gray-900 truncate">{a.title}</h3>
                      <p className="text-sm text-gray-600 mt-2">
                        {a.message.length > 200 ? a.message.substring(0, 200) + "..." : a.message}
                      </p>

                      <div className="mt-4 flex flex-wrap items-center gap-3 text-sm text-gray-600">
                        <span className="inline-flex items-center gap-2">
                          <span className="w-8 h-8 rounded-2xl bg-blue-50 flex items-center justify-center">👤</span>
                          {a.createdBy}
                        </span>
                        <span className="inline-flex items-center gap-2">
                          <span className="w-8 h-8 rounded-2xl bg-blue-50 flex items-center justify-center">🗓️</span>
                          {formatDate(a.createdDate)}
                        </span>
                        <span className="inline-flex items-center gap-2">
                          <span className="w-8 h-8 rounded-2xl bg-blue-50 flex items-center justify-center">⏳</span>
                          Expires: {a.expiresAt}
                        </span>
                      </div>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-2 shrink-0">
                      {!a.read && (
                        <button
                          onClick={() => markAsRead(a.id)}
                          className={btnOutline}
                          style={{ borderColor: "rgba(109,198,223,0.55)", color: "var(--secondary-blue)" }}
                        >
                          Mark as Read
                        </button>
                      )}
                      <Link href={`/staff-dashboard/announcement/${a.id}`}>
                        <button className={btnSolid} style={{ backgroundColor: "var(--primary-blue)" }}>
                          View Details
                        </button>
                      </Link>
                    </div>
                  </div>

                  <div className="mt-5 pt-4 border-t border-gray-200/70 flex flex-wrap items-center justify-between gap-3 text-sm">
                    <div className="flex flex-wrap items-center gap-3 text-gray-600">
                      <span>📄 {a.documents} attachment{a.documents !== 1 ? "s" : ""}</span>
                      <span>💬 {a.comments} comment{a.comments !== 1 ? "s" : ""}</span>
                    </div>

                    <div className="text-xs text-gray-500 inline-flex items-center gap-2">
                      <span className="font-semibold" style={{ color: "var(--primary-blue)" }}>
                        {a.read ? "✅ Read" : "📌 New"}
                      </span>
                      <span>•</span>
                      <span>ID: {a.id}</span>
                    </div>
                  </div>
                </div>

                <div className="px-6 py-3" style={{ backgroundColor: "rgba(109, 198, 223, 0.08)" }}>
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-semibold" style={{ color: "var(--primary-blue)" }}>
                      {a.scope}
                    </span>
                    <span className="text-xs text-gray-600">{a.createdBy}</span>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>

        {filteredAnnouncements.length === 0 && (
          <Card className="p-12 text-center">
            <div className="w-16 h-16 mx-auto rounded-2xl flex items-center justify-center mb-4" style={{ backgroundColor: "rgba(109, 198, 223, 0.12)" }}>
              <span className="text-2xl" style={{ color: "var(--secondary-blue)" }}>
                🧐
              </span>
            </div>
            <h3 className="text-lg font-extrabold text-gray-900 mb-2">No announcements found</h3>
            <p className="text-gray-600">Try adjusting your filters or search term.</p>
          </Card>
        )}

        {/* Important Announcements Summary */}
        <Card className="p-6">
          <h2 className="text-lg font-extrabold mb-4" style={{ color: "var(--primary-blue)" }}>
            Important Announcements Summary
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[
              { type: 'Safety Updates', count: 3, icon: '🛡️', color: 'var(--accent-red)' },
              { type: 'Holiday Schedule', count: 2, icon: '🎄', color: 'var(--secondary-blue)' },
              { type: 'Department News', count: 8, icon: '🏢', color: '#F59E0B' },
            ].map((item) => (
              <div key={item.type} className="p-5 rounded-2xl border text-center" style={{ borderColor: item.color }}>
                <div className="text-3xl mb-2">{item.icon}</div>
                <p className="font-extrabold" style={{ color: item.color }}>{item.type}</p>
                <p className="text-sm text-gray-600 mt-1">{item.count} announcements</p>
              </div>
            ))}
          </div>
        </Card>

        {/* QUICK STATS */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[
            { label: "Total", value: announcementsData.length, icon: "📢", tone: "default" },
            { label: "Unread", value: unreadCount, icon: "📌", tone: "success" },
            { label: "Important/Urgent", value: announcementsData.filter((a) => a.priority === "IMPORTANT" || a.priority === "URGENT").length, icon: "⚠️", tone: "warn" },
            {
              label: "This Month",
              value: announcementsData.filter(a => {
                const annDate = new Date(a.createdDate);
                const now = new Date();
                return annDate.getMonth() === now.getMonth() && annDate.getFullYear() === now.getFullYear();
              }).length,
              icon: "📅",
              tone: "purple",
            },
          ].map((s) => (
            <Card key={s.label} className="p-5">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-500 text-sm font-semibold">{s.label}</p>
                  <p className="text-2xl font-extrabold mt-2">{s.value}</p>
                </div>
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center" style={{ backgroundColor: "rgba(44, 75, 155, 0.08)" }}>
                  <span className="text-xl">{s.icon}</span>
                </div>
              </div>
              <div className="mt-3">
                <Pill tone={s.tone}>{s.label} stat</Pill>
              </div>
            </Card>
          ))}
        </div>
      </div>
    </Layout>
  );
}